const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // PG* env vars
const router = express.Router();

const encode = (ts, id) => Buffer.from(JSON.stringify([ts, id])).toString('base64url');

router.get('/orders', async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

  let cursor = null;
  if (req.query.cursor !== undefined) {
    try {
      cursor = JSON.parse(Buffer.from(String(req.query.cursor), 'base64url').toString());
    } catch {}
    if (!Array.isArray(cursor) || cursor.length !== 2) {
      return res.status(400).json({ error: 'invalid cursor' });
    }
  }

  try {
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
        ${cursor ? 'WHERE (created_at, id) < ($2::timestamptz, $3)' : ''}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      [limit + 1, ...(cursor ?? [])]
    );

    const page = rows.slice(0, limit);
    const last = page.at(-1);
    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: rows.length > limit ? encode(last.cursor_ts, last.id) : null,
    });
  } catch (err) {
    // class 22 = bad cursor values (malformed timestamp / id)
    if (cursor && err.code?.startsWith('22')) {
      return res.status(400).json({ error: 'invalid cursor' });
    }
    next(err);
  }
});

module.exports = router;
